import numpy as np

def softplus(x):
    return np.log(1 + np.exp(x))

def relu(x):
    return np.maximum(0, x)

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def softplus_derivative(x, epsilon=1e-5):
    return (softplus(x + epsilon) - softplus(x - epsilon)) / (2 * epsilon)

test_inputs = np.array([-10, -2, -0.5, 0, 0.5, 2, 10])

print("Input | ReLU | Softplus | Always positive?")
for x in test_inputs:
    print(f"  {x:5.1f} | {relu(x):5.2f} |  {softplus(x):.6f}  |  {'yes' if softplus(x) > 0 else 'no'}")

print("\nVerifying softplus's derivative matches sigmoid:")
for x in [-2, 0, 2]:
    numerical_derivative = softplus_derivative(x)
    sigmoid_value = sigmoid(x)
    print(f"  At x={x}: softplus derivative={numerical_derivative:.4f}, sigmoid value={sigmoid_value:.4f}")
